import React, { useState, useEffect } from "react";

export default function History() {
  const [history, setHistory] = useState([]);

  // Load prediction history from localStorage when the component mounts
  useEffect(() => {
    const stored = localStorage.getItem("predictionHistory");
    if (stored) {
      setHistory(JSON.parse(stored));
    }
  }, []);

  if (history.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "40px", fontFamily: "Arial, sans-serif" }}>
        <h2>Prediction History</h2>
        <p>No predictions yet. Go to the Predict page to make one.</p>
      </div>
    );
  }

  return (
    <div style={{ padding: "20px", maxWidth: "1000px", margin: "0 auto", fontFamily: "Arial, sans-serif" }}>
      <h2 style={{ textAlign: "center", marginBottom: "20px", color: "#333" }}>Prediction History</h2>
      <table style={{ width: "100%", borderCollapse: "collapse", boxShadow: "0 2px 8px rgba(0,0,0,0.1)" }}>
        <thead style={{ backgroundColor: "#282c34", color: "white" }}>
          <tr>
            <th style={thStyle}>Industry</th>
            <th style={thStyle}>Country</th>
            <th style={thStyle}>Company Age</th>
            <th style={thStyle}>Avg Size</th>
            <th style={thStyle}>Current Employees</th>
            <th style={thStyle}>Total Employees</th>
            <th style={thStyle}>Model Type</th>
            <th style={thStyle}>Cluster</th>
            <th style={thStyle}>Prediction</th>
            <th style={thStyle}>Confidence</th>
          </tr>
        </thead>
        <tbody>
          {history.map((item, idx) => (
            <tr key={idx} style={{ textAlign: "center", borderBottom: "1px solid #ddd" }}>
              <td style={tdStyle}>{item.industry_enc}</td>
              <td style={tdStyle}>{item.country_enc}</td>
              <td style={tdStyle}>{item.company_age}</td>
              <td style={tdStyle}>{item.avg_size}</td>
              <td style={tdStyle}>{item.current_employee_estimate}</td>
              <td style={tdStyle}>{item.total_employee_estimate}</td>
              <td style={tdStyle}>{item.model_type}</td>
              <td style={tdStyle}>{item.result.cluster}</td>
              <td style={tdStyle}>{item.result.prediction}</td>
              <td style={tdStyle}>{(item.result.confidence * 100).toFixed(2)}%</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// Styles
const thStyle = { padding: "10px", border: "1px solid #ccc" };
const tdStyle = { padding: "8px", border: "1px solid #ccc" };
